  values ('deal:afc-bournemouth:black-knight-stadium-limited-bkfc:2025-04-25', '2025-04-25', '25 April 2025', 'acquisition', 'sports', 'football', 'AFC Bournemouth', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--afc-bournemouth'), null, 'Black Knight Stadium Limited (BKFC)', 'consortium', (select id from public.companies where lower(name) = lower('Black Knight Stadium Limited (BKFC)') limit 1), (select id from public.sports_investors where lower(name) = lower('Black Knight Stadium Limited (BKFC)') limit 1), 'Structadene', null, null, null, null, null, 'BKFC buys Vitality Stadium back from Structadene', 'A newly created BKFC entity, Black Knight Stadium Limited, entered a binding contract to acquire the Vitality Stadium from property company Structadene, which had owned it since 2005 (bought for £3.5m). No price disclosed; the purchase enables the planned expansion to 20,000+ seats.', 'AFC Bournemouth', 'https://www.afcb.co.uk/news/2025/april/25/afc-bournemouth-announces-acquisition-of-vitality-stadium/', 'web_research')
